def get_max_workload(tau_i, t):
    max_w = 0
    for h in range(1, tau_i.M_i + 1):
        w = compute_multi_segment_workload(tau_i, h, t)
        if w > max_w:
            max_w = w
    return max_w

def calculate_R_SC(tau_k, hp_tasks):
    R = tau_k.C_total + tau_k.S_total
    while True:
        interference = 0
        for tau_i in hp_tasks:
            interference += get_max_workload(tau_i, R)
        new_R = tau_k.C_total + tau_k.S_total + interference
        if new_R == R:
            return R
        if new_R > tau_k.T:
            return float('inf')
        R = new_R

def calculate_segment_response_time(tau_k, j, hp_tasks):
    R = tau_k.C[j]
    while True:
        interference = 0
        for tau_i in hp_tasks:
            interference += get_max_workload(tau_i, R)
        new_R = tau_k.C[j] + interference
        if new_R == R:
            return R
        if new_R > tau_k.T:
            return float('inf')
        R = new_R

def calculate_R_AIR(tau_k, hp_tasks):
    sum_R_segments = 0
    for j in range(1, tau_k.M_k + 1):
        R_j = calculate_segment_response_time(tau_k, j, hp_tasks)
        if R_j == float('inf'): return float('inf')
        sum_R_segments += R_j
    return tau_k.S_total + sum_R_segments

def SCAIR_OPA(tasks):
    n = len(tasks)
    priority_assignment = [None] * n
    unassigned = set(tasks)
    for p in range(n, 0, -1): # From lowest priority to highest
        found = False
        for tau in unassigned:
            hp_tasks = unassigned - {tau}
            if is_SCAIR_schedulable(tau, hp_tasks):
                priority_assignment[p-1] = tau
                unassigned.remove(tau)
                found = True
                break
        if not found:
            return 'No feasible assignment'
    return priority_assignment
